// core/data/connections.js — grouping puzzles for QUARTETS (window.AD_CONNECTIONS).
// Source: hand-authored for this arcade (_build/conn_*.py). Generated by _build/gen_connections.py — do not edit by hand.
// Colours y<g<b<p ascend in difficulty. Every board is verified uniquely solvable; see the trap table in the generator's report.
window.AD_CONNECTIONS = {
"packs":[
{"id":"general","name":"MIXED BAG","blurb":"The main archive. Wordplay, general knowledge, and a purple that bites.","boards":[
{"id":1,"title":"Warm-Up","diff":1,"groups":[{"name":"CITRUS FRUITS","colour":"y","tiles":["LEMON","LIME","ORANGE","POMELO"],"note":"The pomelo is the big one — grapefruit is its child, a pomelo crossed with a sweet orange."},{"name":"SHADES OF BLUE","colour":"g","tiles":["NAVY","COBALT","AZURE","INDIGO"],"note":"Cobalt from the ore, azure from lapis lazuli, indigo from the plant, navy from the Royal Navy's 1748 uniform."},{"name":"___ BALL","colour":"b","tiles":["CRYSTAL","ODD","MEAT","SNOW"],"note":"Crystal ball, oddball, meatball, snowball. Four very different evenings."},{"name":"ANIMALS HIDING INSIDE","colour":"p","tiles":["POTTERY","CRATER","SHAPELY","PROWLER"],"note":"p-OTTER-y, c-RAT-er, sh-APE-ly, pr-OWL-er. You will never read them normally again."}],"epilogue":"A gentle one to calibrate on. If you spent a while looking for a fifth citrus, that's the shape of every board from here: the trick is never the words you know, it's the ones you're sure about."},
{"id":2,"title":"Kitchen Sink","diff":1,"groups":[{"name":"PASTA SHAPES","colour":"y","tiles":["PENNE","FUSILLI","RIGATONI","ORZO"],"note":"Penne means 'quills', fusilli 'little spindles', rigatoni 'ridged'. Orzo means 'barley', which it isn't."},{"name":"KITCHEN UTENSILS","colour":"g","tiles":["SPATULA","WHISK","LADLE","TONGS"],"note":"The four things every drawer has three of and you can never find one."},{"name":"___ PAPER","colour":"b","tiles":["WALL","NEWS","SAND","WASTE"],"note":"Wallpaper, newspaper, sandpaper, wastepaper. Two of them are basically extinct."},{"name":"READ THEM BACKWARDS","colour":"p","tiles":["DIAPER","LAGER","STRAW","DESSERTS"],"note":"Repaid, regal, warts, stressed. DESSERTS/STRESSED is the most quoted word pair in English and the most emotionally accurate."}],"epilogue":"Three groups of things you can hold and one group of things you have to squint at. That ratio is roughly the house style."},
{"id":3,"title":"Board Games Night","diff":1,"groups":[{"name":"CLASSIC BOARD GAMES","colour":"y","tiles":["MONOPOLY","SCRABBLE","CLUEDO","RISK"],"note":"Cluedo outside North America, Clue inside it — same lead pipe, same conservatory."},{"name":"CHESS PIECES","colour":"g","tiles":["PAWN","ROOK","BISHOP","KNIGHT"],"note":"The rook is a castle everywhere except in English chess notation, where it stubbornly stays a bird."},{"name":"CARD GAMES","colour":"b","tiles":["BRIDGE","RUMMY","HEARTS","WHIST"],"note":"Bridge grew out of whist, hearts is a trick-avoidance game, and rummy is the ancestor of half your phone's card apps."},{"name":"___ MATE","colour":"p","tiles":["CHECK","ROOM","SOUL","CLASS"],"note":"Checkmate, roommate, soulmate, classmate — and if you're unlucky, all four at once."}],"epilogue":"CHECK is bait and it is meant to be: it is the only tile that belongs to chess in feeling and to nothing in chess by definition. Count the pieces — there are exactly four without it."},
{"id":4,"title":"Weather Report","diff":2,"groups":[{"name":"PRECIPITATION","colour":"y","tiles":["SLEET","HAIL","DRIZZLE","FLURRY"],"note":"Sleet is the argument between rain and snow; a flurry is snow that isn't committing."},{"name":"CLOUD TYPES","colour":"g","tiles":["CIRRUS","CUMULUS","STRATUS","NIMBUS"],"note":"Luke Howard named them in 1802 in Latin so the whole world could use the same sky."},{"name":"WINDS","colour":"b","tiles":["GALE","ZEPHYR","SQUALL","GUST"],"note":"Zephyrus was the Greek west wind, the mild one. A squall is the opposite temperament."},{"name":"___ STORM","colour":"p","tiles":["BRAIN","SAND","FIRE","THUNDER"],"note":"Brainstorm, sandstorm, firestorm, thunderstorm. Only one of them is scheduled in a calendar."}],"epilogue":"HAIL is the whole puzzle. It is real precipitation and a real storm, and the only way to settle it is to notice that SLEET, DRIZZLE and FLURRY have nowhere else on earth to go."},
{"id":5,"title":"Anatomy Lesson","diff":2,"groups":[{"name":"FLOWERS","colour":"y","tiles":["DAHLIA","PEONY","ASTER","ZINNIA"],"note":"All four are late-summer bloomers, and all four are named after botanists except the aster, which is just Greek for 'star'."},{"name":"BONES","colour":"g","tiles":["FEMUR","TIBIA","ULNA","SCAPULA"],"note":"Thigh, shin, forearm, shoulder blade. The femur is the longest bone you own."},{"name":"PARTS OF THE EYE","colour":"b","tiles":["IRIS","RETINA","CORNEA","PUPIL"],"note":"The pupil is not a thing at all — it is the hole the iris makes."},{"name":"HOMOPHONES OF BODY PARTS","colour":"p","tiles":["MUSSEL","NAVAL","HEAL","LUMBER"],"note":"Muscle, navel, heel, lumbar. Say them out loud and the board rearranges itself."}],"epilogue":"IRIS is a flower. It is also, inconveniently, the only eye part left once RETINA, CORNEA and PUPIL have taken their seats. The flowers already have four; arithmetic beats botany."},
{"id":6,"title":"Screen Time","diff":2,"groups":[{"name":"COMPUTER PERIPHERALS","colour":"y","tiles":["KEYBOARD","MONITOR","MOUSE","PRINTER"],"note":"The four boxes that came with every beige desktop, three of which still work."},{"name":"RODENTS","colour":"g","tiles":["HAMSTER","GERBIL","CAPYBARA","CHINCHILLA"],"note":"The capybara is the largest rodent alive and, by universal agreement, the most relaxed animal on the planet."},{"name":"WEB BROWSERS","colour":"b","tiles":["SAFARI","CHROME","FIREFOX","EDGE"],"note":"Firefox is a red panda, which is not a fox, which is not a rodent either. The naming committee had a night."},{"name":"___ TRACK","colour":"p","tiles":["SOUND","RACE","BACK","SIDE"],"note":"Soundtrack, racetrack, backtrack, sidetrack. The last two are what this board wants you to do."}],"epilogue":"MOUSE is the rodent you were looking for and the rodent you can't have — HAMSTER, GERBIL, CAPYBARA and CHINCHILLA fill the cage without it, and KEYBOARD, MONITOR and PRINTER are three legs of a four-legged desk."},
{"id":7,"title":"Going Places","diff":2,"groups":[{"name":"WAYS TO CROSS WATER","colour":"y","tiles":["FERRY","BRIDGE","TUNNEL","CAUSEWAY"],"note":"A causeway is the cheat: you don't cross the water, you fill it in."},{"name":"AIRPORT FEATURES","colour":"g","tiles":["TERMINAL","CAROUSEL","RUNWAY","CONCOURSE"],"note":"Everything here is a place you stand still, except the one thing that spins."},{"name":"FAIRGROUND ATTRACTIONS","colour":"b","tiles":["WALTZER","DODGEMS","COCONUT SHY","GHOST TRAIN"],"note":"The waltzer spins you, the dodgems dent you, the coconut shy has never in recorded history given up a coconut."},{"name":"___ PORT","colour":"p","tiles":["PASS","CAR","TRANS","SUP"],"note":"Passport, carport, transport, support. Only the first one gets you through the airport."}],"epilogue":"CAROUSEL wants to go to the fairground and the fairground is full. Somebody has to stand at baggage claim."},
{"id":8,"title":"Fully Booked","diff":2,"groups":[{"name":"FINGERS","colour":"y","tiles":["THUMB","RING","PINKY","MIDDLE"],"note":"Anatomists will tell you the thumb is not a finger. Anatomists are not invited to game night."},{"name":"PARTS OF A BOOK","colour":"g","tiles":["SPINE","INDEX","CHAPTER","GLOSSARY"],"note":"The index is the part nobody writes and everybody uses."},{"name":"ONE-WORD SHAKESPEARE PLAYS","colour":"b","tiles":["OTHELLO","MACBETH","CYMBELINE","CORIOLANUS"],"note":"Othello and Macbeth get revived every season; Cymbeline and Coriolanus get revived when a theatre feels brave."},{"name":"___ WORM","colour":"p","tiles":["BOOK","EARTH","SILK","TAPE"],"note":"Bookworm, earthworm, silkworm, tapeworm — in descending order of how much you'd like to be one."}],"epilogue":"Two tiles pull double duty in opposite directions: INDEX is a finger stuck in a book, RING is a finger stuck in a parasite. Follow the ones with no options — SPINE, CHAPTER and GLOSSARY need a fourth, and THUMB, PINKY and MIDDLE need a fourth, and there is exactly one way to feed them both."},
{"id":9,"title":"Music Lesson","diff":2,"groups":[{"name":"WOODWIND INSTRUMENTS","colour":"y","tiles":["OBOE","CLARINET","BASSOON","FLUTE"],"note":"The modern flute is made of metal and is still woodwind, because the family is about how you make the noise, not what out of."},{"name":"ITALIAN MUSICAL DIRECTIONS","colour":"g","tiles":["FORTE","LEGATO","STACCATO","ANDANTE"],"note":"Loud, smooth, detached, walking pace. Andante literally means 'going', which is the most Italian tempo marking possible."},{"name":"TYPES OF SCALE","colour":"b","tiles":["MAJOR","MINOR","CHROMATIC","PENTATONIC"],"note":"The pentatonic scale turns up independently in Chinese, Celtic, West African and blues music — five notes that everybody found on their own."},{"name":"___ NOTE","colour":"p","tiles":["KEY","FOOT","BANK","SIDE"],"note":"Keynote, footnote, banknote, sidenote. Only one of them is ever delivered from a stage."}],"epilogue":"MAJOR and MINOR are keys and scales at once, and KEY is neither — it's a compound word waiting for NOTE. When two tiles could join a group and only one seat is free, take the tile that can't go anywhere else."},
{"id":10,"title":"The Sporting Life","diff":2,"groups":[{"name":"TENNIS SCORING TERMS","colour":"y","tiles":["DEUCE","LOVE","ACE","LET"],"note":"Love for zero probably comes from l'oeuf, the French egg. Deuce from 'à deux', two points to go."},{"name":"IN A DECK OF CARDS","colour":"g","tiles":["JOKER","JACK","CLUBS","SPADES"],"note":"The joker is a 19th-century American invention, added so euchre could have a top trump."},{"name":"GOLF SCORES","colour":"b","tiles":["BIRDIE","EAGLE","BOGEY","ALBATROSS"],"note":"Bogey came first and used to mean par; when standards rose it slid a shot backwards and the birds moved in."},{"name":"___ SHOT","colour":"p","tiles":["LONG","SLAP","BUCK","MUG"],"note":"Longshot, slapshot, buckshot, mugshot. Two sports, one weapon, one bad night."}],"epilogue":"ACE belongs to the cards in every ordinary sense and to tennis in this one; CLUBS belongs to golf in every ordinary sense and to the deck in this one. They swap places in your head and cancel out — the fixed points are DEUCE, LOVE, LET and three birds and a bogey."},
{"id":11,"title":"Full English","diff":3,"groups":[{"name":"ON A FULL ENGLISH PLATE","colour":"y","tiles":["BACON","BLACK PUDDING","BAKED BEANS","HASH BROWN"],"note":"The immovable four, plus egg, sausage, mushrooms, grilled tomato and whatever your café thinks it's doing."},{"name":"BRITISH FOR 'EXCELLENT'","colour":"g","tiles":["CRACKING","SMASHING","BRILLIANT","TOP-NOTCH"],"note":"Three of them describe breaking something. English praise has always had a violent streak."},{"name":"COCKNEY RHYMING SLANG FOR BODY PARTS","colour":"b","tiles":["PLATES OF MEAT","BOAT RACE","MINCE PIES","LOAF OF BREAD"],"note":"Feet, face, eyes, head — and 'use your loaf' is the only one that escaped into general English."},{"name":"___ FAST","colour":"p","tiles":["BREAK","HOLD","STEAD","BEL"],"note":"Breakfast, holdfast, steadfast — and Belfast, which sneaks in on sound alone."}],"epilogue":"Two food groups and one of them isn't food. LOAF OF BREAD is the pivot: put it on the plate and the rhyming slang is a body part short, which is a sentence with an unfortunate double meaning."},
{"id":12,"title":"Elements of Style","diff":3,"groups":[{"name":"NOBLE GASES","colour":"y","tiles":["HELIUM","NEON","ARGON","XENON"],"note":"Argon means 'lazy', xenon means 'stranger', neon means 'new'. Ramsay named most of them and was clearly having fun."},{"name":"SUPERMAN LORE","colour":"g","tiles":["KRYPTONITE","METROPOLIS","LOIS LANE","DAILY PLANET"],"note":"Krypton the planet is named after krypton the noble gas, discovered in 1898 and meaning 'hidden'."},{"name":"ELEMENTS NAMED AFTER PLACES","colour":"b","tiles":["POLONIUM","FRANCIUM","GERMANIUM","AMERICIUM"],"note":"Marie Curie named polonium for a Poland that did not exist on any map in 1898. It was a political act with a chemistry paper attached."},{"name":"___ SIGN","colour":"p","tiles":["PLUS","PEACE","STOP","DOLLAR"],"note":"Plus sign, peace sign, stop sign, dollar sign — a maths symbol, a hand shape, an octagon and a currency."}],"epilogue":"The noble gases and the place-name elements are both periodic-table groups, which is the misdirection — but no noble gas here is named for a place, and nothing in the other four is a gas. NEON is the only tile with a foot in two worlds."},
{"id":13,"title":"Star Turn","diff":3,"groups":[{"name":"ZODIAC SIGNS","colour":"y","tiles":["LIBRA","VIRGO","ARIES","GEMINI"],"note":"Libra is the only zodiac sign that isn't an animal or a person — it's a set of scales."},{"name":"CONSTELLATIONS OUTSIDE THE ZODIAC","colour":"g","tiles":["ORION","CASSIOPEIA","URSA MAJOR","LYRA"],"note":"Cassiopeia was chained to her throne upside down as a punishment for vanity, which is the most Greek sentence available."},{"name":"GALILEAN MOONS OF JUPITER","colour":"b","tiles":["IO","EUROPA","GANYMEDE","CALLISTO"],"note":"Galileo spotted all four in January 1610 and proved not everything orbits us. Ganymede is bigger than Mercury."},{"name":"___ STRUCK","colour":"p","tiles":["STAR","THUNDER","MOON","AWE"],"note":"Starstruck, thunderstruck, moonstruck, awestruck. Every one of them is a way of saying you stopped thinking."}],"epilogue":"Every zodiac sign is also a constellation, which is why the second group had to say 'outside the zodiac' out loud. The only genuinely loose tile is MOON, and IO, EUROPA, GANYMEDE and CALLISTO were never going to make room."},
{"id":14,"title":"Green Room","diff":3,"groups":[{"name":"SHADES OF GREEN","colour":"y","tiles":["OLIVE","EMERALD","JADE","SAGE"],"note":"Three of them are named after a stone, a fruit and a herb. Colour naming has never had an original idea."},{"name":"HERBS","colour":"g","tiles":["BASIL","THYME","OREGANO","TARRAGON"],"note":"Oregano and marjoram are the same genus; tarragon is a relative of wormwood, which explains a lot about tarragon."},{"name":"GEMSTONES","colour":"b","tiles":["GARNET","TOPAZ","OPAL","AMETHYST"],"note":"Amethyst means 'not drunk' — the Greeks believed the stone would keep you sober. It does not."},{"name":"___ HOUSE","colour":"p","tiles":["GREEN","LIGHT","FARM","WARE"],"note":"Greenhouse, lighthouse, farmhouse, warehouse. One grows things, one saves lives, two store things."}],"epilogue":"Four separate tiles want to defect and none of them can, because BASIL, THYME, OREGANO, GARNET, TOPAZ, OPAL and AMETHYST have no second passport at all. Fill the groups that have no choices first and the colours are whatever survives."},
{"id":15,"title":"Small Talk","diff":3,"groups":[{"name":"WORDS MEANING TINY","colour":"y","tiles":["PETITE","SLIGHT","WEE","MINUTE"],"note":"MY-newt, not MIN-it. Same spelling, different word, different Latin root — and the whole reason this board exists."},{"name":"UNITS OF TIME","colour":"g","tiles":["SECOND","FORTNIGHT","DECADE","MILLENNIUM"],"note":"Fortnight is 'fourteen nights' worn down by seven centuries of use, and Americans have never adopted it."},{"name":"A BRIEF MOMENT, INFORMALLY","colour":"b","tiles":["JIFFY","TICK","FLASH","HEARTBEAT"],"note":"A jiffy is genuinely a unit in physics and electronics — anywhere from a millisecond to the time light takes to cross a fermi."},{"name":"___ GLASS","colour":"p","tiles":["HOUR","SPY","PLEXI","LOOKING"],"note":"Hourglass, spyglass, plexiglass, looking glass. Two for seeing far, one for seeing yourself, one for seeing time run out."}],"epilogue":"MINUTE and HOUR both look like clock parts and neither one is. Notice that SECOND, FORTNIGHT, DECADE and MILLENNIUM already make four, and the rest of the board unlocks in about a second."},
{"id":16,"title":"Say That Again","diff":3,"groups":[{"name":"PALINDROMES","colour":"y","tiles":["CIVIC","RADAR","MADAM","KAYAK"],"note":"Radar is an acronym that happens to read the same both ways, which its inventors did not plan and have never stopped being asked about."},{"name":"NO VOWEL LETTERS","colour":"g","tiles":["RHYTHM","CRYPT","LYNX","GYPSY"],"note":"Y is doing all the work in three of these and none of it in the fourth."},{"name":"CONTAIN ALL FIVE VOWELS","colour":"b","tiles":["SEQUOIA","FACETIOUS","EDUCATION","DIALOGUE"],"note":"FACETIOUS has them in order, A-E-I-O-U, which is the only reason anybody remembers the word."},{"name":"THEIR OWN OPPOSITE","colour":"p","tiles":["CLEAVE","SANCTION","DUST","OVERSIGHT"],"note":"Cleave together or apart, sanction it or ban it, dust a cake or a shelf, oversight as care or as failure. Contronyms — English arguing with itself."}],"epilogue":"A rare board with no double agents: every tile qualifies for exactly one group and the difficulty is entirely in noticing what the groups are. If the purple took you a while, that's the intended shape — the connection is a property of the word, not of the thing."},
{"id":17,"title":"Menu Reading","diff":3,"groups":[{"name":"WAYS TO SERVE EGGS","colour":"y","tiles":["POACHED","SCRAMBLED","CODDLED","OVER EASY"],"note":"Coddled means barely set in a lidded pot in gentle water — the technique that gave us the verb for spoiling someone."},{"name":"FRENCH MOTHER SAUCES","colour":"g","tiles":["BÉCHAMEL","VELOUTÉ","ESPAGNOLE","HOLLANDAISE"],"note":"Carême named four; Escoffier added tomate and made it five. Every classical French sauce is a child of one of them."},{"name":"PROTECTED-ORIGIN CHEESES","colour":"b","tiles":["ROQUEFORT","MANCHEGO","STILTON","GRUYÈRE"],"note":"Stilton's protection is famously strict — it cannot legally be made in the village of Stilton, which is in the wrong county."},{"name":"___ WHITE","colour":"p","tiles":["EGG","SNOW","OFF","BONE"],"note":"Egg white, snow white, off-white, bone white. Two are colours on a paint chart, one is a fairy tale, one is breakfast."}],"epilogue":"The egg group is about methods, not ingredients — POACHED, SCRAMBLED, CODDLED and OVER EASY are all things you do, and EGG is a thing you have. Hollandaise, incidentally, is made of egg and belongs to France instead."},
{"id":18,"title":"Island Life","diff":3,"groups":[{"name":"ISLAND COUNTRIES","colour":"y","tiles":["CYPRUS","ICELAND","FIJI","JAMAICA"],"note":"Fiji is about 330 islands; Iceland is essentially one; Cyprus is one island and, unhappily, two administrations."},{"name":"GREEK ISLANDS","colour":"g","tiles":["CRETE","RHODES","NAXOS","SANTORINI"],"note":"Santorini is the rim of a volcano that blew its own middle out around 1600 BC and possibly took Minoan Crete with it."},{"name":"FICTIONAL ISLANDS","colour":"b","tiles":["LILLIPUT","ATLANTIS","NEVERLAND","AMITY"],"note":"Amity is the beach town in Jaws, whose mayor kept it open. Atlantis is Plato's, invented for an argument about hubris."},{"name":"ADD 'LAND' FOR A COUNTRY","colour":"p","tiles":["FIN","IRE","POL","THAI"],"note":"Finland, Ireland, Poland, Thailand. ICE would have worked too, which is exactly why it's already spoken for."}],"epilogue":"ICELAND is the joke: it is a genuine island country and it is also, letter for letter, ICE plus LAND. It sits in the group that needs it, and the purple has to make do with FIN, IRE, POL and THAI."},
{"id":19,"title":"Money Talks","diff":3,"groups":[{"name":"CURRENCIES","colour":"y","tiles":["PESO","DINAR","RUPEE","KRONA"],"note":"Dinar comes from the Roman denarius and rupee from Sanskrit rupya, 'wrought silver'. Money words travel further than money."},{"name":"SLANG FOR MONEY","colour":"g","tiles":["DOUGH","BREAD","QUID","LOOT"],"note":"Dough and bread say the same thing twice: money is what you eat with."},{"name":"SQUARES ON A UK MONOPOLY BOARD","colour":"b","tiles":["MAYFAIR","OLD KENT ROAD","FREE PARKING","WATER WORKS"],"note":"Mayfair costs £400 and Old Kent Road £60, a ratio London property has spent a century trying to beat."},{"name":"___ BANK","colour":"p","tiles":["BLOOD","RIVER","PIGGY","DATA"],"note":"Blood bank, river bank, piggy bank, data bank. Only one of them holds money, and it's the pig."}],"epilogue":"QUID is the honest ambiguity here — it names a real currency the way 'buck' names the dollar. PESO, DINAR, RUPEE and KRONA are the four that appear on actual banknotes, and slang gets what's left."},
{"id":20,"title":"Get a Grip","diff":3,"groups":[{"name":"KNOTS","colour":"y","tiles":["REEF","BOWLINE","CLOVE HITCH","SHEEPSHANK"],"note":"The bowline is the one you can untie after it's been loaded; the reef knot is the one everybody ties and half of them tie as a granny."},{"name":"MARTIAL ARTS","colour":"g","tiles":["JUDO","AIKIDO","KARATE","CAPOEIRA"],"note":"Capoeira was developed by enslaved Africans in Brazil and disguised as dance, which is why it is fought to music."},{"name":"YOGA POSES","colour":"b","tiles":["COBRA","WARRIOR","CHILD'S POSE","DOWNWARD DOG"],"note":"Downward dog is adho mukha svanasana; the warrior is virabhadrasana, named for a rather angry avatar of Shiva."},{"name":"___ HOLD","colour":"p","tiles":["HOUSE","STRONG","FREE","THRESH"],"note":"Household, stronghold, freehold, threshold. Three kinds of property and one doorway."}],"epilogue":"Every group here is about grip, stance or holding on, so the categories blur by design. WARRIOR is the tile that reads as combat and isn't — JUDO, AIKIDO, KARATE and CAPOEIRA are the four that actually hit back."},
{"id":21,"title":"Table for Two","diff":3,"groups":[{"name":"COFFEE ORDERS","colour":"y","tiles":["LATTE","CORTADO","MACCHIATO","FLAT WHITE"],"note":"A cortado is equal parts espresso and warm milk; a macchiato is espresso 'stained' with a spoonful. The flat white is an antipodean argument that never ended."},{"name":"TEAS AND INFUSIONS","colour":"g","tiles":["OOLONG","ROOIBOS","MATCHA","DARJEELING"],"note":"Rooibos is not tea at all — it's a South African bush — and matcha is the whole leaf ground up rather than steeped and thrown away."},{"name":"COCKTAILS NAMED AFTER PLACES","colour":"b","tiles":["MANHATTAN","MOSCOW MULE","LONG ISLAND","BRONX"],"note":"The Bronx is a 1900s gin, vermouth and orange juice cocktail that was once as famous as the Martini and is now ordered by nobody."},{"name":"___ PRESS","colour":"p","tiles":["FRENCH","BENCH","CIDER","PRINTING"],"note":"French press, bench press, cider press, printing press. All four squeeze something out of something else."}],"epilogue":"FRENCH is the only tile with a foot in the café. LATTE, CORTADO, MACCHIATO and FLAT WHITE are drinks you order by name, and a French press is a piece of equipment — which is the distinction the board is testing."},
{"id":22,"title":"Loose Change","diff":3,"groups":[{"name":"US COINS","colour":"y","tiles":["PENNY","NICKEL","DIME","QUARTER"],"note":"The dime is the smallest US coin by size and the only one that doesn't say what it's worth anywhere on it."},{"name":"METALS","colour":"g","tiles":["TITANIUM","TIN","ZINC","LEAD"],"note":"Titanium is as strong as steel and 45% lighter; lead is soft enough to scratch with a fingernail."},{"name":"BRITISH SLANG FOR PRISON","colour":"b","tiles":["CLINK","NICK","SLAMMER","POKEY"],"note":"The Clink was a real gaol in Southwark from the 12th century until a mob burned it down in 1780. The name outlived the building by 250 years."},{"name":"___ MINE","colour":"p","tiles":["GOLD","LAND","COAL","DIAMOND"],"note":"Gold mine, landmine, coal mine, diamond mine. Only one of them you'd rather not find."}],"epilogue":"NICKEL is a metal that got a coin named after it, and NICK is a prison that sounds like the metal. TITANIUM, TIN, ZINC and LEAD have never been legal tender in America, so the metal shelf fills without it."},
{"id":23,"title":"Strike Anywhere","diff":4,"groups":[{"name":"THINGS YOU STRIKE","colour":"y","tiles":["MATCH","DEAL","POSE","BALANCE"],"note":"You strike a match, a deal, a pose and a balance — four completely unrelated verbs wearing the same coat."},{"name":"OLYMPIC ATHLETICS EVENTS","colour":"g","tiles":["HURDLES","JAVELIN","SHOT PUT","STEEPLECHASE"],"note":"The steeplechase has a water jump because it descends from a horse race across country between two church steeples."},{"name":"PARTS OF A DRUM KIT","colour":"b","tiles":["SNARE","HI-HAT","CYMBAL","TOM"],"note":"The snare is named for the wires stretched under the bottom head; without them it's just a very disappointed tom."},{"name":"___ STICK","colour":"p","tiles":["CHAP","YARD","DRUM","LIP"],"note":"Chapstick, yardstick, drumstick, lipstick. Two of them go on your face."}],"epilogue":"Two tiles argue about the same kit: DRUM wants to join the drums and CYMBAL wants to join the things you strike, and they cancel out. SNARE, HI-HAT and TOM cannot be anything else, and MATCH, DEAL and POSE cannot be anything else, so the leftovers sort themselves."},
{"id":24,"title":"Alphabet Soup","diff":4,"groups":[{"name":"GREEK LETTERS","colour":"y","tiles":["SIGMA","DELTA","OMEGA","LAMBDA"],"note":"Sigma became the summation sign, delta the symbol for change, lambda the wavelength, and omega the end of everything."},{"name":"NATO ALPHABET WORDS","colour":"g","tiles":["TANGO","FOXTROT","WHISKEY","ROMEO"],"note":"The 1956 alphabet was tested across accents and radio static; the words were chosen because they survive being half-heard, not because they're pretty."},{"name":"BALLROOM DANCES","colour":"b","tiles":["WALTZ","QUICKSTEP","RUMBA","SAMBA"],"note":"The quickstep came out of the 1920s when bands played the foxtrot too fast and the dancers simply kept up."},{"name":"___ FORCE","colour":"p","tiles":["AIR","TASK","BRUTE","WORK"],"note":"Air force, task force, brute force, workforce. Only one of them is a solution to a maths problem."}],"epilogue":"Two of the NATO words are dances and one of the Greek letters is a NATO word, so three tiles are pulling sideways at once. The anchor is that SIGMA, OMEGA and LAMBDA are Greek and nothing else — DELTA has to stay to make four, and once it does, TANGO and FOXTROT have to stay too."},
{"id":25,"title":"Silent Treatment","diff":4,"groups":[{"name":"SILENT B","colour":"y","tiles":["DEBT","SUBTLE","PLUMBER","DOUBT"],"note":"Debt and doubt never had a B in English — 16th-century scholars inserted them to show off the Latin, and we've been silently paying for it since."},{"name":"SILENT K","colour":"g","tiles":["KNEEL","KNUCKLE","KNACK","KNOLL"],"note":"The K was pronounced until about 1600. Chaucer's knight was a k-nicht."},{"name":"SILENT P","colour":"b","tiles":["PSALM","PNEUMONIA","RECEIPT","CORPS"],"note":"Greek gave us the ps- and pn- pairs and English refused to say either. Corps is French and drops the P and the S together."},{"name":"SILENT L","colour":"p","tiles":["SALMON","CALM","YOLK","WOULD"],"note":"Salmon had no L at all until Latin-minded spellers put one in, and nobody has ever pronounced it."}],"epilogue":"PSALM is the double agent and the resolution is arithmetic, not phonetics: SALMON, CALM, YOLK and WOULD already make four silent Ls, and PNEUMONIA, RECEIPT and CORPS need a fourth silent P. There is only one word that can do the job."},
{"id":26,"title":"Two of a Kind","diff":4,"groups":[{"name":"THINGS THAT COME IN PAIRS","colour":"y","tiles":["SCISSORS","TROUSERS","BINOCULARS","TWEEZERS"],"note":"All four are grammatically plural and physically singular, which is why you buy 'a pair' of each."},{"name":"___ SOME","colour":"g","tiles":["HAND","AWE","TIRE","LONE"],"note":"Handsome, awesome, tiresome, lonesome. 'Handsome' originally meant easy to handle."},{"name":"COLLECTIVE NOUNS FOR BIRDS","colour":"b","tiles":["MURDER","PARLIAMENT","CHARM","MURMURATION"],"note":"A murder of crows, a parliament of owls, a charm of finches, a murmuration of starlings. Most were invented in a 15th-century hunting manual by people showing off."},{"name":"QUARK FLAVOURS","colour":"p","tiles":["UP","DOWN","STRANGE","BOTTOM"],"note":"Six flavours: up, down, strange, charm, top and bottom. Gell-Mann took 'quark' from a line in Finnegans Wake and the naming has been unserious ever since."}],"epilogue":"CHARM is a quark and a flock, and both readings are completely legitimate — which is why UP, DOWN, STRANGE and BOTTOM had to be four on their own. MURDER, PARLIAMENT and MURMURATION have no subatomic ambitions."},
{"id":27,"title":"Shades of Meaning","diff":4,"groups":[{"name":"WORDS MEANING FAKE","colour":"y","tiles":["BOGUS","PHONY","SHAM","ERSATZ"],"note":"Ersatz is German for 'replacement' and entered English through wartime coffee made of acorns."},{"name":"WORDS MEANING STUBBORN","colour":"g","tiles":["DOGGED","MULISH","OBSTINATE","PIGHEADED"],"note":"Three of these blame an animal for a human failing, which is the most human thing about them."},{"name":"ADJECTIVES FROM ANIMALS","colour":"b","tiles":["BOVINE","FELINE","ASININE","VULPINE"],"note":"Cow, cat, ass, fox. Only asinine has drifted so far from the donkey that people forget it was ever about one."},{"name":"___ FACED","colour":"p","tiles":["TWO","BARE","POKER","STONE"],"note":"Two-faced, barefaced, poker-faced, stone-faced. Three are expressions and one is a character judgement."}],"epilogue":"Three tiles in the stubborn group are literally adjectives made from animals, which looks like a fatal ambiguity and isn't: BOVINE, FELINE, ASININE and VULPINE are already four, and none of them means stubborn. The animal group is full before the argument starts."},
{"id":28,"title":"Take Your Pick","diff":4,"groups":[{"name":"PARTS OF A GUITAR","colour":"y","tiles":["FRET","NUT","TUNING PEG","SOUNDHOLE"],"note":"The nut is the slotted strip at the top of the neck that sets the string spacing and the open-string height. Get it wrong and nothing else can be right."},{"name":"NUTS","colour":"g","tiles":["CASHEW","PECAN","MACADAMIA","WALNUT"],"note":"Botanically almost none of these is a nut — the cashew is a seed hanging off a fruit, the pecan and walnut are drupes."},{"name":"SCREWDRIVER HEADS","colour":"b","tiles":["PHILLIPS","FLATHEAD","TORX","HEX"],"note":"Phillips was designed to cam out on purpose so an assembly-line driver couldn't overtighten. Every stripped screw since is a feature."},{"name":"___ PICK","colour":"p","tiles":["ICE","TOOTH","NIT","HAND"],"note":"Ice pick, toothpick, nitpick, handpick. Two are objects, two are habits."}],"epilogue":"NUT is the whole board. CASHEW, PECAN, MACADAMIA and WALNUT are four already, and FRET, TUNING PEG and SOUNDHOLE are three looking for a fourth — which is exactly the sort of counting that makes a purple collapse."},
{"id":29,"title":"Long Story Short","diff":4,"groups":[{"name":"ACRONYMS THAT BECAME ORDINARY WORDS","colour":"y","tiles":["LASER","SCUBA","TASER","SONAR"],"note":"Light Amplification by Stimulated Emission of Radiation; Self-Contained Underwater Breathing Apparatus; Sound Navigation and Ranging. Nobody has expanded any of them out loud since 1975."},{"name":"PORTMANTEAU WORDS","colour":"g","tiles":["BRUNCH","SMOG","MOTEL","PODCAST"],"note":"Smog is smoke plus fog and was coined in 1905 about London. Podcast is iPod plus broadcast, which now outlives the iPod."},{"name":"WORDS FROM A PERSON'S NAME","colour":"b","tiles":["SANDWICH","BOYCOTT","CARDIGAN","SILHOUETTE"],"note":"The Earl of Sandwich, Captain Boycott who was frozen out by his tenants, the Earl of Cardigan of Light Brigade fame, and Étienne de Silhouette, a finance minister so stingy his name meant 'done on the cheap'."},{"name":"THEIR OWN PLURAL","colour":"p","tiles":["SHEEP","DEER","SERIES","AIRCRAFT"],"note":"One sheep, two sheep. English gave up on these and never came back."}],"epilogue":"TASER is genuinely both: an acronym and a word from somebody's name, because the acronym IS somebody's name. SANDWICH, BOYCOTT, CARDIGAN and SILHOUETTE are already four earls and a civil servant, so the acronyms keep their stun gun."},
{"id":30,"title":"Hidden Depths","diff":4,"groups":[{"name":"SEAS","colour":"y","tiles":["CORAL","BALTIC","ARAL","TASMAN"],"note":"The Aral is the cautionary one — it was the fourth-largest lake on earth in 1960 and is now mostly desert with rusting trawlers in it."},{"name":"SHADES OF RED","colour":"g","tiles":["CRIMSON","SCARLET","VERMILION","CARMINE"],"note":"Carmine and crimson both come from the kermes insect, crushed for dye since antiquity. Vermilion is ground cinnabar, which is mercury ore, which is why old painters died young."},{"name":"MUSIC GENRES","colour":"b","tiles":["SKA","GRIME","DRILL","GARAGE"],"note":"Ska came first in Jamaica, garage out of New York and then very differently out of London, and grime and drill out of that. Four genres, one family tree."},{"name":"___ BAND","colour":"p","tiles":["ARM","HEAD","WAIST","BROAD"],"note":"Armband, headband, waistband, broadband. Three of them hold something up."}],"epilogue":"CORAL is a colour that got a sea named after it, which is the reverse of how these usually go. CRIMSON, SCARLET, VERMILION and CARMINE are four reds already, and BALTIC, ARAL and TASMAN are three seas short of a set."},
{"id":31,"title":"Change of Address","diff":5,"groups":[{"name":"GREETINGS AROUND THE WORLD","colour":"y","tiles":["ALOHA","CIAO","SALAAM","NAMASTE"],"note":"Aloha and ciao both mean hello AND goodbye; salaam and namaste are both blessings that got shortened into doorway small talk."},{"name":"EUROPEAN CAPITALS","colour":"g","tiles":["LISBON","TALLINN","ZAGREB","VILNIUS"],"note":"Lisbon is older than Rome; Tallinn's old town survived the twentieth century almost intact, which almost nothing in the Baltics did."},{"name":"FOUR-LETTER COUNTRIES","colour":"b","tiles":["CHAD","PERU","IRAN","LAOS"],"note":"There are seven or eight depending on how you count Cuba, Fiji, Mali and Togo. These four are the ones that fit."},{"name":"ANAGRAMS OF EUROPEAN CAPITALS","colour":"p","tiles":["MORE","SOLO","PAIRS","HASTEN"],"note":"Rome, Oslo, Paris, Athens. Four ordinary English words hiding four capitals, none of which are the four capitals in the second group."}],"epilogue":"LAOS and SOLO are anagrams of the same capital, which is the trick: only one of them can sit in the purple, and LAOS has a day job. CHAD, PERU and IRAN aren't anagrams of anything European, so the countries need their fourth."},
{"id":32,"title":"Elementary","diff":4,"groups":[{"name":"SHERLOCK HOLMES THINGS","colour":"y","tiles":["BAKER STREET","DEERSTALKER","MORIARTY","WATSON"],"note":"Conan Doyle never wrote 'elementary, my dear Watson' and never described a deerstalker — the hat was Sidney Paget's idea in The Strand."},{"name":"FICTIONAL DETECTIVES","colour":"g","tiles":["POIROT","MARPLE","MAIGRET","WIMSEY"],"note":"Christie got so tired of Poirot she called him a detestable little creature in her diary and kept writing him for another forty years."},{"name":"FAMOUS COMPUTERS","colour":"b","tiles":["DEEP BLUE","HAL","ALPHAGO","ENIAC"],"note":"ENIAC in 1945 filled a room and weighed 27 tonnes; Deep Blue beat Kasparov in 1997; AlphaGo beat Lee Sedol in 2016 with a move no human would have played."},{"name":"___ HOUND","colour":"p","tiles":["GREY","NEWS","FOX","WOLF"],"note":"Greyhound, newshound, foxhound, wolfhound. The Baskerville one is not on the list and you should be grateful."}],"epilogue":"WATSON is a doctor and a computer, and both are famous enough to earn a seat. DEEP BLUE, HAL, ALPHAGO and ENIAC are already four machines, so the doctor goes back to Baker Street — which is where the deerstalker, incidentally, never actually was."},
{"id":33,"title":"Kitchen Chemistry","diff":4,"groups":[{"name":"THINGS THAT RISE","colour":"y","tiles":["SOUFFLÉ","TIDE","SUN","CURTAIN"],"note":"A soufflé rises because trapped water turns to steam, not because of anything magical. The curtain rises because someone pulls a rope."},{"name":"LEAVENING AGENTS","colour":"g","tiles":["YEAST","BAKING SODA","BAKING POWDER","EGG WHITE"],"note":"Yeast is alive, baking soda needs an acid to react with, baking powder brings its own acid, and egg white just traps air and holds on."},{"name":"___ PROOF","colour":"b","tiles":["FOOL","WATER","BULLET","FIRE"],"note":"Foolproof, waterproof, bulletproof, fireproof. In a bakery, 'proof' means letting the dough rise, which is a different word entirely."},{"name":"FRENCH COOKING TECHNIQUES","colour":"p","tiles":["SAUTÉ","BLANCH","FLAMBÉ","JULIENNE"],"note":"Sauté means 'jumped', blanchir means 'to whiten', flamber means 'to flame'. Julienne is somebody's name and nobody is sure whose."}],"epilogue":"The joke is buried in the purple: to 'proof' dough is to let it rise, so the ___ PROOF group is thematically perfect and grammatically irrelevant. YEAST makes things rise rather than rising itself, and SOUFFLÉ, TIDE, SUN and CURTAIN do the rising in person."},
{"id":34,"title":"Sound Alike","diff":5,"groups":[{"name":"HOMOPHONES OF NUMBERS","colour":"y","tiles":["WON","TOO","FOR","ATE"],"note":"One, two, four, eight. English numbers collide with English grammar words more than any other language has the decency to allow."},{"name":"HOMOPHONES OF ANIMALS","colour":"g","tiles":["BARE","DEAR","HAIR","YEW"],"note":"Bear, deer, hare, ewe. Three of them are things you'd find in an English wood and one is a churchyard tree that sounds like a sheep."},{"name":"HOMOPHONES OF WEATHER","colour":"b","tiles":["REIGN","HALE","SON","DUE"],"note":"Rain, hail, sun, dew. 'Hale' as in hale and hearty — from the same root as 'whole', nothing to do with the ice."},{"name":"HOMOPHONES OF MUSICAL NOTES","colour":"p","tiles":["DOUGH","RAY","ME","TEA"],"note":"Do, re, mi, ti. The solfège syllables come from the first lines of a Latin hymn to John the Baptist, which is a long way to go for a scale."}],"epilogue":"Every tile is a homophone of something, so the categories are four different somethings — and the trap is that RAY is genuinely a fish, not merely a word that sounds like one. BARE, DEAR, HAIR and YEW are all one letter away from a mammal, and none of them is an animal itself."},
{"id":35,"title":"State of Play","diff":5,"groups":[{"name":"US STATE CAPITALS","colour":"y","tiles":["ALBANY","PIERRE","SALEM","AUSTIN"],"note":"Pierre, South Dakota has about 14,000 people and is the second-smallest state capital in the country."},{"name":"SHAKESPEARE'S ITALIAN SETTINGS","colour":"g","tiles":["VERONA","VENICE","PADUA","MESSINA"],"note":"Verona for Romeo and Juliet, Venice for the Merchant and Othello, Padua for the Shrew, Messina for Much Ado. He never went to any of them."},{"name":"___ CITY","colour":"b","tiles":["KANSAS","CARSON","ATLANTIC","SIOUX"],"note":"Kansas City is mostly in Missouri, Atlantic City is on an island, and Sioux City and Sioux Falls are in different states."},{"name":"___ ROCK","colour":"p","tiles":["PUNK","PLYMOUTH","BED","SHAM"],"note":"Punk rock, Plymouth Rock, bedrock, shamrock. Only one of them is a plant and it isn't even a rock."}],"epilogue":"CARSON is a state capital wearing a compound word's clothes, and the only reason it can't be one here is that ALBANY, PIERRE, SALEM and AUSTIN already are four. KANSAS, ATLANTIC and SIOUX need a fourth city and Carson is the only one going."},
{"id":36,"title":"Well Suited","diff":4,"groups":[{"name":"PARTS OF A SUIT JACKET","colour":"y","tiles":["LAPEL","CUFF","VENT","LINING"],"note":"The vent is the slit at the back: none is Italian, one is American, two is English. Tailors will fight you about this."},{"name":"TYPES OF COLLAR","colour":"g","tiles":["MANDARIN","PETER PAN","BUTTON-DOWN","SHAWL"],"note":"The button-down was invented for polo players so the collar wouldn't flap in their faces at a gallop."},{"name":"SUITS IN A TAROT DECK","colour":"b","tiles":["WANDS","CUPS","SWORDS","PENTACLES"],"note":"Wands, cups, swords and pentacles map onto clubs, hearts, spades and diamonds — the tarot came first and the playing deck simplified it."},{"name":"___ LINK","colour":"p","tiles":["MISSING","WEAK","SAUSAGE","CHAIN"],"note":"Missing link, weak link, sausage link, chain link. Two are metaphors, one is a fence, one is breakfast."}],"epilogue":"Two different meanings of 'suit' share a board, which is the misdirection, and CUFF is the tile that actually moves. MISSING, WEAK, SAUSAGE and CHAIN are four links already, so the cuff stays sewn to the sleeve."},
{"id":37,"title":"No Rhyme","diff":4,"groups":[{"name":"WORDS WITH NO PERFECT RHYME","colour":"y","tiles":["ORANGE","SILVER","PURPLE","MONTH"],"note":"There is a hill in Wales called Blorenge and a Scrabble-legal word 'chilver', which is how determined people get about this."},{"name":"KINDS OF PUZZLE","colour":"g","tiles":["SUDOKU","ANAGRAM","REBUS","ACROSTIC"],"note":"Sudoku is Japanese for 'the digits are limited to one occurrence', which is less catchy and more accurate."},{"name":"SPELLED ONLY WITH ROMAN NUMERALS","colour":"b","tiles":["MIX","DIM","MILD","CIVIL"],"note":"Every letter is I, V, X, L, C, D or M. MIX is genuinely 1009 and DIM is genuinely 1499, which is a coincidence English did not plan."},{"name":"COUNTRIES HIDING INSIDE","colour":"p","tiles":["PIRANHA","INCUBATE","NORMALITY","ROMANCE"],"note":"p-IRAN-ha, in-CUBA-te, nor-MALI-ty, r-OMAN-ce. Four countries in four words that have nothing to do with them."}],"epilogue":"No double agents — this board is hard because two of the four categories are properties of the spelling rather than the meaning, and your brain keeps trying to sort by topic. MIX and DIM look like they belong with the puzzles until you notice what letters they are made of."},
{"id":38,"title":"Crossed Wires","diff":5,"groups":[{"name":"TYPES OF CURRENT","colour":"y","tiles":["ALTERNATING","DIRECT","RIP","EDDY"],"note":"Two are electrical and two are water. Eddy currents are actually both — loops of electricity induced in metal, named after the whirl in a river."},{"name":"PARTS OF A CIRCUIT","colour":"g","tiles":["RESISTOR","CAPACITOR","DIODE","FUSE"],"note":"A fuse is a component designed to destroy itself, which is a rare and honourable job description."},{"name":"THINGS YOU BLOW","colour":"b","tiles":["WHISTLE","KISS","BUBBLE","GASKET"],"note":"Blow a whistle, a kiss, a bubble, a gasket. Only one of them costs money to fix."},{"name":"___ WIRE","colour":"p","tiles":["HAY","HIGH","LIVE","TRIP"],"note":"Haywire, high wire, live wire, tripwire. 'Haywire' comes from farm equipment repaired with baling wire until it stopped working entirely."}],"epilogue":"Three tiles are pulling toward the mains and none of them can go: RESISTOR, CAPACITOR and DIODE need a fourth component, and WHISTLE, KISS and BUBBLE need a fourth thing to blow, and there is exactly one tile that can satisfy either. Blow a gasket, blow a fuse — only one of those is a component."},
{"id":39,"title":"Full Circle","diff":5,"groups":[{"name":"PARTS OF A CIRCLE","colour":"y","tiles":["RADIUS","CHORD","ARC","TANGENT"],"note":"A chord joins two points on the circle, an arc is the bit between them, a tangent touches at exactly one point and then leaves forever."},{"name":"MUSIC THEORY TERMS","colour":"g","tiles":["TRIAD","CADENCE","OCTAVE","INTERVAL"],"note":"A triad is three notes stacked in thirds, a cadence is how a phrase lands, an octave is the interval so consonant we gave both notes the same name."},{"name":"TRIGONOMETRIC FUNCTIONS","colour":"b","tiles":["SINE","COSINE","COSECANT","COTANGENT"],"note":"'Sine' is a mistranslation: Sanskrit jya became Arabic jiba, was misread as jaib meaning 'bay', and was rendered into Latin as sinus. The word means 'fold' by accident."},{"name":"___ POINT","colour":"p","tiles":["TURNING","BOILING","PIN","VIEW"],"note":"Turning point, boiling point, pinpoint, viewpoint. Only one of them has a temperature."}],"epilogue":"CHORD and TANGENT both have a completely legitimate second home, and both are trapped by counting: TRIAD, CADENCE, OCTAVE and INTERVAL are already four, and SINE, COSINE, COSECANT and COTANGENT are already four. RADIUS and ARC would be a very lonely group of two."},
{"id":40,"title":"The Last Word","diff":5,"groups":[{"name":"SYNONYMS FOR 'END'","colour":"y","tiles":["FINALE","CONCLUSION","TERMINUS","CLOSE"],"note":"Four different registers of the same idea: theatrical, logical, geographical and plain."},{"name":"AT A RAILWAY STATION","colour":"g","tiles":["PLATFORM","SIGNAL BOX","BUFFERS","SLEEPER"],"note":"The buffers are the shock absorbers at the end of the line, which is why 'hit the buffers' means what it means."},{"name":"PARTS OF A PLAY","colour":"b","tiles":["ACT","SCENE","PROLOGUE","EPILOGUE"],"note":"The prologue tells you what you're about to see and the epilogue tells you what it meant. Everything worth watching is in between."},{"name":"___ CURTAIN","colour":"p","tiles":["IRON","SHOWER","LACE","FINAL"],"note":"Iron curtain, shower curtain, lace curtain, final curtain. The iron one in a theatre is a real fire barrier, which is where Churchill got the phrase."}],"epilogue":"The last board in the archive and it is entirely about endings, which felt like the right note. TERMINUS is the tile that could go either way, and PLATFORM, SIGNAL BOX, BUFFERS and SLEEPER settle it by being four already. Final curtain."}
]},
{"id":"persia","name":"PERSIAN BLUE","blurb":"Shahnameh, Nowruz, poets, food, and the words English quietly borrowed.","boards":[
{"id":1,"title":"Haft-Sin","diff":1,"groups":[{"name":"THE SEVEN S's OF THE HAFT-SIN","colour":"y","tiles":["SABZEH","SAMANU","SENJED","SERKEH"],"note":"Sprouted wheat, wheat pudding, oleaster berries, vinegar — plus seeb (apple), seer (garlic) and somaq to make seven, all beginning with the letter sin."},{"name":"NOWRUZ CUSTOMS","colour":"g","tiles":["SIZDAH BEDAR","FIRE JUMPING","KHANE TAKANI","EIDI"],"note":"Thirteenth-day picnic, the last-Wednesday bonfires of Chaharshanbe Suri, the deep spring clean, and the crisp new banknotes the elders hand out."},{"name":"MONTHS OF THE PERSIAN CALENDAR","colour":"b","tiles":["FARVARDIN","ORDIBEHESHT","KHORDAD","ESFAND"],"note":"The year starts at the spring equinox with Farvardin and ends with Esfand. Iran's calendar is solar and, in astronomical terms, more accurate than the Gregorian one."},{"name":"ALSO ON THE NOWRUZ TABLE, BUT NOT AN 'S'","colour":"p","tiles":["GOLDFISH","MIRROR","CANDLES","DIVAN OF HAFEZ"],"note":"The mirror for light, the candles for fire, the goldfish for life — and Hafez, opened at random on the night, to tell you how your year will go."}],"epilogue":"The whole board sits on one table, which is the joke: eight of these things are laid out together every March and the only thing separating them is a letter of the alphabet. Say each word out loud and the sin group announces itself."},
{"id":2,"title":"The Seven Trials","diff":2,"groups":[{"name":"HEROES OF THE SHAHNAMEH","colour":"y","tiles":["ROSTAM","SOHRAB","ESFANDIYAR","ZAL"],"note":"Zal was born white-haired, abandoned, and raised by the Simorgh. His son Rostam holds the epic together for a third of its length."},{"name":"SHAHNAMEH VILLAINS","colour":"g","tiles":["ZAHHAK","AFRASIYAB","SUDABEH","GARSIVAZ"],"note":"Zahhak grew serpents from his shoulders that had to be fed on human brains, which is a thousand years old and still the best villain design in the business."},{"name":"OBSTACLES OF ROSTAM'S HAFT KHAN","colour":"b","tiles":["LION","DRAGON","SORCERESS","WHITE DEMON"],"note":"Seven trials on the road to Mazandaran: the lion Rakhsh kills alone, the thirst, the dragon, the sorceress, Ulad, Arzhang, and finally Div-e Sepid."},{"name":"ROSTAM'S HORSE, COAT AND WEAPONS","colour":"p","tiles":["RAKHSH","BABR-E BAYAN","GORZ","KAMAND"],"note":"Rakhsh the stallion, the babr-e bayan that no weapon could pierce, the ox-headed mace and the lasso. He is the only hero whose horse gets its own reputation."}],"epilogue":"Two tiles argue about which shelf they belong on and both lose: ZAHHAK, AFRASIYAB, SUDABEH and GARSIVAZ are already four villains, and ROSTAM, SOHRAB, ESFANDIYAR and ZAL are already four heroes. Rakhsh gets filed with the tack."},
{"id":3,"title":"The Poets","diff":3,"groups":[{"name":"CLASSICAL PERSIAN POETS","colour":"y","tiles":["HAFEZ","SAADI","RUMI","FERDOWSI"],"note":"Ferdowsi spent about thirty years on the Shahnameh and is credited with saving the Persian language from being written out of existence."},{"name":"THE BOOKS THEY WROTE","colour":"g","tiles":["DIVAN","GOLESTAN","MASNAVI","SHAHNAMEH"],"note":"Hafez's Divan, Saadi's Golestan ('rose garden'), Rumi's Masnavi, Ferdowsi's Shahnameh ('book of kings'). Four books, one shelf, most Iranian homes."},{"name":"PERSIAN POETIC FORMS","colour":"b","tiles":["GHAZAL","RUBAI","QASIDA","DOBEYTI"],"note":"The ghazal is the love lyric, the rubai the four-line epigram Khayyam made famous in English, the qasida the long formal ode, the dobeyti the folk couplet."},{"name":"CITIES WITH A POET'S TOMB","colour":"p","tiles":["SHIRAZ","TUS","KONYA","NISHAPUR"],"note":"Hafez AND Saadi in Shiraz, Ferdowsi at Tus, Rumi at Konya in Turkey, Khayyam at Nishapur. Iranians visit these the way other countries visit battlefields."}],"epilogue":"Rumi's book is called The Masnavi because it is written in masnavi form, and Hafez's book is called The Divan because a divan is what a collection is called. The titles ARE the forms. GHAZAL, RUBAI, QASIDA and DOBEYTI have no such double life, so let them fill the form group first."},
{"id":4,"title":"At the Sofreh","diff":2,"groups":[{"name":"KEBABS","colour":"y","tiles":["KOOBIDEH","BARG","JOOJEH","SOLTANI"],"note":"Koobideh is minced and pounded, barg is a thin fillet, joojeh is chicken in saffron and lemon, and soltani is one skewer of each because you couldn't decide."},{"name":"PERSIAN STEWS","colour":"g","tiles":["GHORMEH SABZI","FESENJAN","GHEYMEH","KHORESH-E BEH"],"note":"Ghormeh sabzi is the national dish and the one every family swears their mother makes best. Fesenjan is walnut and pomegranate, sweet and sour and dark as ink."},{"name":"RICE DISHES","colour":"b","tiles":["TAHCHIN","ZERESHK POLO","BAGHALI POLO","ADAS POLO"],"note":"Polo means the rice is cooked with something in it; the real prize is tahdig, the crust at the bottom, over which families have genuinely fallen out."},{"name":"PERSIAN SWEETS","colour":"p","tiles":["GAZ","SOHAN","BAMIEH","ZOOLBIA"],"note":"Gaz is Isfahan's nougat, sohan is Qom's saffron brittle, and zoolbia and bamieh are the syrup-soaked pair that appear in every Ramadan window."}],"epilogue":"BAMIEH is a sweet named after a vegetable that names a stew, which is the most Persian sentence on this board. GAZ, SOHAN and ZOOLBIA have no such ambiguity, and the stew group is full before you get there."},
{"id":5,"title":"The Map","diff":2,"groups":[{"name":"IRANIAN CITIES","colour":"y","tiles":["ISFAHAN","SHIRAZ","TABRIZ","MASHHAD"],"note":"'Isfahan is half the world' was a 17th-century boast and, standing in Naqsh-e Jahan square, still a defensible one."},{"name":"IRAN'S NEIGHBOURS","colour":"g","tiles":["IRAQ","ARMENIA","PAKISTAN","TURKMENISTAN"],"note":"Seven land borders in all: Iraq, Turkey, Armenia, Azerbaijan, Turkmenistan, Afghanistan and Pakistan."},{"name":"PERSIAN DYNASTIES","colour":"b","tiles":["ACHAEMENID","SASSANID","SAFAVID","QAJAR"],"note":"Achaemenid from Cyrus, Sassanid until the Arab conquest, Safavid who made Iran Shia and built Isfahan, Qajar who lost the Caucasus and invented Iranian photography."},{"name":"IRAN'S WATERS AND DESERTS","colour":"p","tiles":["CASPIAN","DASHT-E KAVIR","LUT","PERSIAN GULF"],"note":"The Lut recorded a land-surface temperature of about 70°C by satellite, among the hottest ever measured anywhere on Earth."}],"epilogue":"Four flat categories and no tricks — this one is a geography lesson wearing a puzzle's clothes. If you know that Armenia and Iran share a short mountain border, everything else falls out."},
{"id":6,"title":"Words You Already Use","diff":4,"groups":[{"name":"PERSIAN LOANWORDS YOU WEAR","colour":"y","tiles":["PYJAMAS","SHAWL","KHAKI","TURBAN"],"note":"Pay-jama, 'leg garment'. Shal. Khak, 'dust'. Dulband, the cloth you wind round a head."},{"name":"PERSIAN LOANWORDS YOU EAT OR DRINK","colour":"g","tiles":["JULEP","SPINACH","PISTACHIO","CANDY"],"note":"Golab (rosewater) became julep; esfanaj became spinach; pesteh became pistachio; qand, a lump of crystallised sugar, became candy."},{"name":"PERSIAN LOANWORDS THAT GROW OR GLOW","colour":"b","tiles":["LILAC","TULIP","JASMINE","AZURE"],"note":"Nilak the bluish one, yasmin the flower, lazhward the lapis stone that gave Europe both azure and ultramarine — and tulip, from dulband again, because the flower looks like a turban."},{"name":"PERSIAN LOANWORDS NOBODY EXPECTS","colour":"p","tiles":["PARADISE","CHECKMATE","MAGIC","MUMMY"],"note":"Pairidaeza, a walled garden. Shah mat, 'the king is helpless'. Magush, the Zoroastrian priest-caste the Greeks called magoi. And mum, wax — what Persian embalming used."}],"epilogue":"Every tile on this board is an English word that came from Persian, so the categories are four different reasons for the same fact. TULIP and TURBAN are the same Persian word arriving twice, six hundred years apart, which is the sort of thing that happens when a language is old enough."},
{"id":7,"title":"Knots and Strings","diff":3,"groups":[{"name":"PERSIAN MUSICAL INSTRUMENTS","colour":"y","tiles":["TAR","SANTUR","KAMANCHEH","TOMBAK"],"note":"The tar's body is two joined bowls covered in lambskin; the santur is struck with tiny wooden hammers; the kamancheh is bowed and stands on a spike."},{"name":"CARPET-WEAVING CITIES","colour":"g","tiles":["TABRIZ","KASHAN","KERMAN","NAIN"],"note":"You can date and place a Persian carpet from its knot count and palette alone — Nain is famously fine, Tabriz famously dense."},{"name":"PERSIAN CRAFTS","colour":"b","tiles":["KHATAM","MINAKARI","GHALAMZANI","TERMEH"],"note":"Khatam is micro-mosaic marquetry, minakari is enamel on copper, ghalamzani is hammer-and-chisel engraving, termeh is the woven wool that predates paisley."},{"name":"MOTIFS IN A PERSIAN CARPET","colour":"p","tiles":["BOTEH","GOL","MEDALLION","TREE OF LIFE"],"note":"The boteh is the teardrop the Scottish town of Paisley copied and got the credit for. The central medallion is the toranj."}],"epilogue":"Two of these groups are made by hand in the same workshops and one of them is played in the next room, which is why the board feels blurrier than it is. Nothing here fits twice — the difficulty is purely in knowing which craft is which."},
{"id":8,"title":"Two Thousand Years","diff":3,"groups":[{"name":"PERSIAN KINGS","colour":"y","tiles":["CYRUS","DARIUS","XERXES","SHAPUR"],"note":"Cyrus's cylinder is often called the first charter of its kind; Shapur I captured a Roman emperor alive and carved it into a cliff at Naqsh-e Rostam."},{"name":"CAPITALS OF PERSIAN EMPIRES","colour":"g","tiles":["PERSEPOLIS","CTESIPHON","PASARGADAE","SUSA"],"note":"Pasargadae was Cyrus's, Persepolis the ceremonial one Alexander burned, Susa the administrative workhorse, Ctesiphon the Parthian and Sasanian seat on the Tigris."},{"name":"ANCIENT PERSIAN ENGINEERING","colour":"b","tiles":["QANAT","YAKHCHAL","BADGIR","CHAHAR BAGH"],"note":"A qanat carries groundwater tens of kilometres underground by gravity alone; a yakhchal made and kept ice in the desert; a badgir is a tower that air-conditions a house with no power at all."},{"name":"ZOROASTRIAN WORDS","colour":"p","tiles":["AHURA MAZDA","AVESTA","FARAVAHAR","ATASHKADEH"],"note":"Ahura Mazda the wise lord, the Avesta the scripture, the faravahar the winged figure now worn as a necklace by half the diaspora, and the atashkadeh where the fire is kept."}],"epilogue":"The engineering group is the one modern Iran is proudest of and the one outsiders know least: QANAT, YAKHCHAL and BADGIR are all climate technology a thousand years early. ATASHKADEH is a building too, but it belongs to the faith that built it."},
{"id":9,"title":"Tehran","diff":4,"groups":[{"name":"TEHRAN LANDMARKS","colour":"y","tiles":["AZADI TOWER","MILAD TOWER","TABIAT BRIDGE","GRAND BAZAAR"],"note":"Azadi was built in 1971 and has been the backdrop to every side of every argument since. Tabiat is a three-level pedestrian bridge designed by Leila Araghian, who was 26."},{"name":"MOUNTAINS ABOVE THE CITY","colour":"g","tiles":["DAMAVAND","ALBORZ","TOCHAL","DARBAND"],"note":"Damavand is 5,610 m, the highest peak in the Middle East, and in the Shahnameh it is where Fereydun chains Zahhak."},{"name":"IRANIAN FILMMAKERS","colour":"b","tiles":["KIAROSTAMI","FARHADI","PANAHI","MAKHMALBAF"],"note":"Kiarostami took the Palme d'Or in 1997, Farhadi has two foreign-language Oscars, and Panahi has made several films while banned from making films."},{"name":"PERSIAN FAMILY WORDS","colour":"p","tiles":["MADAR","PEDAR","KHAHAR","BARADAR"],"note":"Mother, father, sister, brother — and if you look at them long enough you can see the Indo-European family resemblance to the English ones."}],"epilogue":"TOCHAL is the argument: it is a peak with a tourist attraction bolted to it. DAMAVAND, ALBORZ and DARBAND are unarguably geology, and AZADI TOWER, MILAD TOWER, TABIAT BRIDGE and GRAND BAZAAR are unarguably built, so the mountain keeps its rock."},
{"id":10,"title":"Rose and Nightingale","diff":4,"groups":[{"name":"DASTGAH — THE PERSIAN MUSICAL MODES","colour":"y","tiles":["SHUR","MAHUR","HOMAYUN","SEGAH"],"note":"Seven dastgah and five avaz between them cover the whole classical repertoire. Shur is the melancholy one and by far the most used."},{"name":"GREAT IRANIAN SINGERS","colour":"g","tiles":["SHAJARIAN","GOOGOOSH","BANAN","DELKASH"],"note":"Shajarian's 'Rabbana' is played every Ramadan; Googoosh was the pop star of a whole era and then did not sing in public for twenty-one years."},{"name":"SUFI WORDS YOU'D HEAR IN PERSIAN","colour":"b","tiles":["SAMA","FANA","ISHQ","DERVISH"],"note":"Sama is the listening-and-turning ceremony, fana the annihilation of the self, ishq the love that causes it, dervish the one who has given up owning things."},{"name":"THE STOCK IMAGES OF A GHAZAL","colour":"p","tiles":["ROSE","NIGHTINGALE","WINE","MOTH"],"note":"Gol and bolbol, the rose and the nightingale who loves her hopelessly; the wine that may or may not be actual wine; the moth who flies into the candle on purpose."}],"epilogue":"Persian poetry and Persian mysticism use the same words on purpose, so WINE genuinely belongs to two worlds — that ambiguity is the art form, not a bug in the puzzle. The clean line is language: SAMA, FANA, ISHQ and DERVISH are Persian words carried into English, and ROSE, NIGHTINGALE, WINE and MOTH are plain English nouns doing symbolic work."},
{"id":11,"title":"The Kitchen Table","diff":4,"groups":[{"name":"PERSIAN INGREDIENTS ON AN AMERICAN SHELF","colour":"y","tiles":["SAFFRON","BARBERRIES","ROSEWATER","POMEGRANATE"],"note":"Saffron is bloomed in hot water first, never sprinkled dry; barberries are fried in butter for thirty seconds and no longer or they turn black."},{"name":"PERSIAN NAMES THAT MEAN A FLOWER","colour":"g","tiles":["YASMIN","NILOOFAR","LALEH","GOLNAR"],"note":"Jasmine, water lily, tulip, and pomegranate blossom. Persian first names are frequently just the nicest noun available."},{"name":"ON THE SOFREH AQD","colour":"b","tiles":["MIRROR","CANDELABRA","ESFAND","HONEY"],"note":"The bride sees her groom first in the mirror; esfand seeds burn against the evil eye; the couple feed each other honey so the marriage starts sweet."},{"name":"WHAT THEY ACTUALLY SAY TO YOU","colour":"p","tiles":["GHORBOONET","JOON","AZIZAM","TAAROF"],"note":"'May I be sacrificed for you' as a casual goodbye; 'joon' after your name as affection; 'azizam' for my dear; and taarof, the ritual refusal that everybody performs and nobody means."}],"epilogue":"This board is somebody's actual house. ROSEWATER and ESFAND live in two rooms of it at once, which is why the resolution has to come from the tiles that don't: SAFFRON, BARBERRIES and POMEGRANATE are groceries, MIRROR, CANDELABRA and HONEY are wedding, and the rest sorts itself."},
{"id":12,"title":"Count to Four","diff":5,"groups":[{"name":"PRINCES OF THE SHAHNAMEH WHO DIE YOUNG","colour":"y","tiles":["IRAJ","SIYAVASH","SOHRAB","ESFANDIYAR"],"note":"Iraj murdered by his brothers, Siyavash beheaded in exile, Sohrab killed by a father who didn't know him, Esfandiyar shot through both eyes by Rostam on Simorgh's advice. The epic is mostly a book about fathers and sons going wrong."},{"name":"PERSIAN WORDS FOR POWER","colour":"g","tiles":["SHAH","SHAHANSHAH","VIZIER","SATRAP"],"note":"King, king of kings, the minister who runs everything, and the provincial governor whose title the Greeks borrowed and never gave back."},{"name":"CREATURES OF PERSIAN MYTH","colour":"b","tiles":["SIMORGH","DIV","PERI","HOMA"],"note":"The Simorgh is a benevolent giant bird; a div is a demon; a peri is where the word 'fairy' partly comes from; the homa never lands and whoever its shadow falls on becomes king."},{"name":"COUNT TO FOUR IN PERSIAN","colour":"p","tiles":["YEK","DO","SE","CHAHAR"],"note":"Yek, do, se, chahar. 'Do' is two, which is why Chaharshanbe is the fourth day and the bonfire night is the last one of the year."}],"epilogue":"The hardest board in the pack, and the way in is the smallest tiles: YEK, DO, SE and CHAHAR are two and three letters long and mean nothing in English, which is exactly the shape of a purple. Solve those four first and the epic sorts itself out behind them."}
]},
{"id":"united","name":"RED DEVILS","blurb":"Old Trafford lore. Sibling to FOURMATIONS — no group is repeated from it.","boards":[
{"id":1,"title":"Home Ground","diff":1,"groups":[{"name":"MANCHESTER BANDS","colour":"y","tiles":["OASIS","THE SMITHS","JOY DIVISION","NEW ORDER"],"note":"Joy Division became New Order after Ian Curtis died in 1980 — technically half a group, and the only reason both fit."},{"name":"SIR ALEX FERGUSON MANAGED THEM","colour":"g","tiles":["EAST STIRLING","ST MIRREN","ABERDEEN","SCOTLAND"],"note":"East Stirlingshire in 1974 with eight players and no goalkeeper. Aberdeen broke the Old Firm and beat Real Madrid. Scotland he took to Mexico '86 after Jock Stein died at Ninian Park."},{"name":"UNITED'S HOME GROUNDS","colour":"b","tiles":["NORTH ROAD","BANK STREET","OLD TRAFFORD","MAINE ROAD"],"note":"North Road 1878, Bank Street 1893, Old Trafford 1910 — and Maine Road from 1946 to 1949, because the Luftwaffe had flattened Old Trafford and City lent them the ground."},{"name":"MANCHESTER PLACES","colour":"p","tiles":["CURRY MILE","CANAL STREET","THE HACIENDA","DEANSGATE"],"note":"The Haçienda was funded by New Order's record sales and lost money on every pint it ever sold. FAC 51, 1982 to 1997."}],"epilogue":"The gentlest board in the pack and it still has a sting: two of the grounds are also just places in Manchester, and one of them belonged to City. Count the venues United actually played home matches at — there are exactly four, and the Haçienda is not one of them."},
{"id":2,"title":"Numbers Up","diff":2,"groups":[{"name":"UNITED'S RECORD APPEARANCE MAKERS","colour":"y","tiles":["GIGGS","CHARLTON","SCHOLES","FOULKES"],"note":"963, 758, 718, 688. Giggs's total is not going to be beaten by anybody, ever, in any sport, in this country."},{"name":"WORE UNITED'S NO. 10","colour":"g","tiles":["ROONEY","SHERINGHAM","VAN NISTELROOY","RASHFORD"],"note":"Squad numbers only arrived in 1993–94. Since then the 10 has been a striker's shirt without exception."},{"name":"PLAYED IN THE 1968 EUROPEAN CUP FINAL","colour":"b","tiles":["STILES","CRERAND","ASTON","DUNNE"],"note":"Wembley, 4–1 after extra time, ten years and three months after Munich. John Aston had the game of his life on the left wing and nobody remembers."},{"name":"___ CARD","colour":"p","tiles":["RED","WILD","POST","FLASH"],"note":"Red card, wildcard, postcard, flashcard. Only one of them gets you an early bath."}],"epilogue":"Two men played in 1968 and are also in the all-time top four, which is not a coincidence — that is what a career at one club looks like. STILES, CRERAND, ASTON and DUNNE have only one qualification between them, so the final fills itself and the appearance list takes the leftovers."},
{"id":3,"title":"The Caretakers","diff":2,"groups":[{"name":"UNITED'S KIT MANUFACTURERS","colour":"y","tiles":["ADMIRAL","ADIDAS","UMBRO","NIKE"],"note":"Admiral 1975, Adidas 1980, Umbro 1992, Nike 2002, Adidas again from 2015. The 1992 Umbro deal outfitted the first Premier League title in 26 years."},{"name":"TOOK CHARGE OF UNITED IN A CARETAKER OR INTERIM SPELL","colour":"g","tiles":["GIGGS","CARRICK","RANGNICK","VAN NISTELROOY"],"note":"Giggs after Moyes in 2014, Carrick after Solskjær in 2021, Rangnick for the rest of that season, Van Nistelrooy for four games in 2024. Carrick won two and drew one and left."},{"name":"BEAT UNITED IN AN FA CUP FINAL","colour":"b","tiles":["SOUTHAMPTON","EVERTON","CHELSEA","MAN CITY"],"note":"Southampton 1976 (Bobby Stokes, second division), Everton 1995, Chelsea twice, City in 2023 — the first all-Manchester final in the competition's history."},{"name":"UNITED NICKNAMES","colour":"p","tiles":["SPARKY","CHOCCY","THE GUV'NOR","WAZZA"],"note":"Mark Hughes, Brian McClair, Paul Ince and Wayne Rooney. Ince gave himself his; that is the entire personality of Paul Ince."}],"epilogue":"No double agents on this one — the difficulty is entirely in knowing that Rangnick's title was 'interim manager' and Carrick's lasted three matches. If the nicknames went last, that is the correct order of operations."},
{"id":4,"title":"Bloodlines","diff":3,"groups":[{"name":"UNITED'S DUTCHMEN","colour":"y","tiles":["BLIND","DE LIGT","WEGHORST","DEPAY"],"note":"Daley Blind's father Danny won the European Cup with Ajax; Daley won the Europa League with United in 2017."},{"name":"SCOTS AT OLD TRAFFORD","colour":"g","tiles":["MCCLAIR","MCTOMINAY","DENIS LAW","FLETCHER"],"note":"McClair scored 24 in his first season, the first United player past 20 since Best. Law is still the only Scot to win the Ballon d'Or."},{"name":"CAME THROUGH UNITED'S ACADEMY","colour":"b","tiles":["RASHFORD","MAINOO","WELBECK","WES BROWN"],"note":"United have named an academy graduate in every matchday squad since October 1937 — the longest unbroken run in English football."},{"name":"OLD ___","colour":"p","tiles":["TRAFFORD","FIRM","MASTER","TIMER"],"note":"Old Trafford, Old Firm, old master, old timer. Only one of them is a ground, and it isn't the one in Glasgow."}],"epilogue":"Two Scots are also academy boys, which is what happens when a club scouts north of the border for a hundred years. RASHFORD, MAINOO, WELBECK and WES BROWN can only be one thing, so the academy is full before the Scots even sit down."},
{"id":5,"title":"Those Other Nights in Europe","diff":3,"groups":[{"name":"UNITED'S EUROPEAN CUP FINAL OPPONENTS","colour":"y","tiles":["BENFICA","BAYERN","CHELSEA","BARCELONA"],"note":"Benfica 1968, Bayern 1999, Chelsea 2008, Barcelona 2009 and 2011. Two won, three lost — and Barcelona did it twice, which still stings."},{"name":"SCORED FOR UNITED IN A EUROPEAN FINAL","colour":"g","tiles":["BEST","KIDD","SHERINGHAM","RONALDO"],"note":"Best and Kidd in extra time at Wembley in '68 — Kidd on his 19th birthday. Sheringham in Barcelona, Ronaldo with a header in the Moscow rain."},{"name":"IN UNITED'S EUROPEAN TROPHY CABINET","colour":"b","tiles":["EUROPEAN CUP","EUROPA LEAGUE","UEFA SUPER CUP","CLUB WORLD CUP"],"note":"Three European Cups, the 1991 Cup Winners' Cup and Super Cup, the 1999 Intercontinental, the 2008 Club World Cup, and Mourinho's Europa League in 2017."},{"name":"___ CUP","colour":"p","tiles":["BUTTER","HIC","TEA","EGG"],"note":"Buttercup, hiccup, teacup, egg cup. None of them has ever been paraded round Deansgate on an open-top bus."}],"epilogue":"Four groups, three of them about silverware, and the last one about a flower and a spasm of the diaphragm. The purple is a relief valve — after three rows of European history, the answer is that CUP was never the point."},
{"id":6,"title":"Word on the Shirt","diff":4,"groups":[{"name":"UNITED MEN WITH A WORLD CUP WINNER'S MEDAL","colour":"y","tiles":["STILES","SCHWEINSTEIGER","POGBA","L. MARTÍNEZ"],"note":"Stiles won his at United in 1966; Schweinsteiger arrived with his in 2015; Pogba won his as a United player in 2018; Lisandro Martínez had been at the club four months when Argentina won in 2022."},{"name":"COLOURS IN THE SURNAME","colour":"g","tiles":["BLACKMORE","WHITESIDE","GREENHOFF","BROWN"],"note":"Clayton Blackmore, Norman Whiteside, the Greenhoff brothers and Wes Brown — a full paint chart, all of them genuinely United."},{"name":"UNITED SURNAMES THAT ARE ORDINARY WORDS","colour":"b","tiles":["BUTT","PARK","BLIND","MAY"],"note":"Nicky Butt, Park Ji-sung, Daley Blind, David May. Read the team sheet as a sentence and it nearly works."},{"name":"ON THE MANCHESTER UNITED CREST","colour":"p","tiles":["SHIP","TRIDENT","RED DEVIL","FOOTBALLS"],"note":"The ship comes from Manchester's city arms and the Ship Canal; the devil arrived in the 1960s from the rugby league nickname Busby borrowed."}],"epilogue":"BROWN is the honest double-fit: a colour AND a word you'd find in a dictionary. The resolution is that BLACKMORE, WHITESIDE and GREENHOFF are not words, so the colour group needs BROWN more than the word group does — and BUTT, PARK and BLIND make four on their own."},
{"id":7,"title":"Crossing the Line","diff":4,"groups":[{"name":"PLAYED FOR UNITED AND LIVERPOOL","colour":"y","tiles":["MICHAEL OWEN","PAUL INCE","BEARDSLEY","CHISNALL"],"note":"Phil Chisnall in 1964 is still the last player transferred directly between the two clubs. Beardsley played one match for United, in a League Cup tie in 1982, and was sold."},{"name":"UNITED OLD BOYS IN THE PUNDIT'S CHAIR","colour":"g","tiles":["KEANE","SCHOLES","RIO FERDINAND","G. NEVILLE"],"note":"Keane's job is to be appalled, Neville's is to explain why, Ferdinand's is to laugh, and Scholes's is to say four words and leave."},{"name":"SURVIVED MUNICH AND PLAYED FOR UNITED AGAIN","colour":"b","tiles":["BOBBY CHARLTON","BILL FOULKES","HARRY GREGG","DENNIS VIOLLET"],"note":"6 February 1958. Gregg went back into the burning aircraft twice and pulled out a baby and her mother. Viollet came back and scored 32 league goals in 1959–60, still a club record."},{"name":"___ FORD","colour":"p","tiles":["TRAF","OX","BED","SAL"],"note":"Trafford, Oxford, Bedford, Salford — and Salford City is the one the Class of '92 bought."}],"epilogue":"MICHAEL OWEN is a pundit and a man who played for both, and the pundit chair only seats four. KEANE, SCHOLES, RIO FERDINAND and G. NEVILLE never wore red and Liverpool red, so they get the studio and Owen gets the awkward CV."},
{"id":8,"title":"Full Time","diff":5,"groups":[{"name":"BEATEN BY UNITED IN A LEAGUE CUP FINAL","colour":"y","tiles":["NOTTM FOREST","WIGAN","SPURS","NEWCASTLE"],"note":"1992, 2006, 2009, 2023. The 1992 win over Forest was United's first League Cup and Brian Clough's last final."},{"name":"UNITED'S ARGENTINES","colour":"g","tiles":["VERÓN","HEINZE","GARNACHO","ROJO"],"note":"Verón cost £28.1m in 2001 and confused everybody including himself. Rojo scored maybe three goals and one of them was a 93rd-minute winner in the Champions League."},{"name":"WON THE BALLON D'OR AS A UNITED PLAYER","colour":"b","tiles":["LAW","CHARLTON","BEST","RONALDO"],"note":"1964, 1966, 1968 — three in five years, the Holy Trinity in order — and then a gap of forty years until Ronaldo in 2008."},{"name":"___ RED","colour":"p","tiles":["CODE","INFRA","SEEING","BLOOD"],"note":"Code red, infrared, seeing red, blood red. Four kinds of alarm and not one of them a football club."}],"epilogue":"The hardest board in the pack, and both traps are language rather than football: CHARLTON reads as a club and ROJO reads as a colour. Neither can move, because NOTTM FOREST, WIGAN, SPURS and NEWCASTLE are already four, and so are CODE, INFRA, SEEING and BLOOD. Verón would have been proud of the misdirection and baffled by the execution."}
]},
{"id":"office","name":"OFFICE HOURS","blurb":"Meetings, calendars, Slack, and the vocabulary of getting things shipped.","boards":[
{"id":1,"title":"Calendar Tetris","diff":1,"groups":[{"name":"KINDS OF MEETING","colour":"y","tiles":["STANDUP","ALL-HANDS","ONE-ON-ONE","RETRO"],"note":"The standup is meant to be fifteen minutes standing up. It is neither."},{"name":"CALENDAR SETTINGS","colour":"g","tiles":["TENTATIVE","RECURRING","BUSY","DECLINE"],"note":"'Recurring' is how a thirty-minute meeting quietly becomes twenty-six hours a year."},{"name":"SLACK STATUSES","colour":"b","tiles":["IN A MEETING","OUT SICK","HEADS DOWN","ON A CALL"],"note":"Only one of these is ever set honestly and it is the one with the thermometer emoji."},{"name":"___ ROOM","colour":"p","tiles":["BOARD","BREAK","WAR","GREEN"],"note":"Boardroom, break room, war room, green room. An office contains at most one of them and calls it all four."}],"epilogue":"BUSY is the only word here that lives in two apps at once. IN A MEETING, OUT SICK, HEADS DOWN and ON A CALL are sentences you type at a person; TENTATIVE, RECURRING and DECLINE are buttons you click at a machine."},
{"id":2,"title":"Reply All","diff":2,"groups":[{"name":"EMAIL SIGN-OFFS","colour":"y","tiles":["BEST","REGARDS","CHEERS","THANKS"],"note":"'Best' is the safe one, 'Regards' is the cold one, 'Cheers' is the one that gives you away as British, and 'Thanks' depends entirely on the punctuation."},{"name":"PASSIVE-AGGRESSIVE EMAIL","colour":"g","tiles":["PER MY LAST","CIRCLING BACK","AS DISCUSSED","GENTLE NUDGE"],"note":"'Per my last email' means you did not read my last email. 'As discussed' means you agreed to this and I have receipts."},{"name":"BUTTONS IN A MAIL CLIENT","colour":"b","tiles":["REPLY ALL","FORWARD","ARCHIVE","SNOOZE"],"note":"Snooze was invented so a message could be ignored on a schedule rather than at random."},{"name":"___ BOX","colour":"p","tiles":["IN","OUT","SAND","CHECK"],"note":"Inbox, outbox, sandbox, checkbox. Two are full, one is empty, one is where the good ideas go."}],"epilogue":"THANKS is a sign-off and a threat depending on the punctuation, which is exactly why it's here. BEST, REGARDS and CHEERS have no hidden edge, so the sign-off group needs a fourth and the passive-aggressive group already has one."},
{"id":3,"title":"Ship It","diff":3,"groups":[{"name":"PROJECT TRACKERS","colour":"y","tiles":["ASANA","TRELLO","JIRA","NOTION"],"note":"Every team migrates between these roughly every eighteen months and the tasks never survive the move."},{"name":"TASK STATUSES","colour":"g","tiles":["BLOCKED","IN PROGRESS","BACKLOG","DONE"],"note":"'Backlog' is the polite word for the place work goes to be quietly forgotten."},{"name":"CORPORATE VERBS","colour":"b","tiles":["LEVERAGE","IDEATE","ONBOARD","SOCIALISE"],"note":"All four already had perfectly good meanings and were taken anyway. 'Socialise' used to mean going to a party."},{"name":"___ BOARD","colour":"p","tiles":["KAN","ON","WHITE","DASH"],"note":"Kanban, onboard, whiteboard, dashboard. The first one is where the second one gets explained on the third one and reported on the fourth."}],"epilogue":"ONBOARD is the pivot and the purple gives it away: ON is already in the compound group, so ONBOARD cannot be. LEVERAGE, IDEATE and SOCIALISE are three verbs looking for a fourth, and there is only one candidate on the board."},
{"id":4,"title":"Out of Office","diff":3,"groups":[{"name":"WAYS TO SAY YOU'RE AWAY","colour":"y","tiles":["PTO","OOO","ANNUAL LEAVE","SABBATICAL"],"note":"PTO is American, annual leave is British, OOO is what the auto-reply calls it, and a sabbatical is the one you have to earn."},{"name":"OFFICE FURNITURE","colour":"g","tiles":["TASK CHAIR","PHONE BOOTH","WHITEBOARD","MONITOR ARM"],"note":"The phone booth is the single best purchase an open-plan office ever makes and the last one it ever budgets for."},{"name":"VIDEO-CALL DISASTERS","colour":"b","tiles":["MUTE","FROZEN","ECHO","CAT FILTER"],"note":"The cat filter incident of 2021 involved a Texas judge, a county attorney and the sentence 'I'm here live, I'm not a cat.'"},{"name":"___ DESK","colour":"p","tiles":["HOT","HELP","FRONT","STANDING"],"note":"Hot desk, help desk, front desk, standing desk. Only one of them belongs to a person."}],"epilogue":"STANDING is furniture in spirit and a compound in fact. TASK CHAIR, PHONE BOOTH, WHITEBOARD and MONITOR ARM are already four things you could put in a van, so the desk group keeps its fourth leg."},
{"id":5,"title":"Grant Cycle","diff":4,"groups":[{"name":"PARTS OF A GRANT PROPOSAL","colour":"y","tiles":["ABSTRACT","BUDGET","TIMELINE","DELIVERABLES"],"note":"The abstract is written last, the budget is written first, and the timeline is written by an optimist."},{"name":"ACADEMIC JOB TITLES","colour":"g","tiles":["POSTDOC","FELLOW","DEAN","CHAIR"],"note":"'Chair' is the head of a department and 'Dean' the head of a school, and no two universities agree on which outranks the other."},{"name":"WHAT THE OFFICE MANAGER ORDERS","colour":"b","tiles":["NAMETAGS","COFFEE PODS","EXTENSION LEAD","FLIP CHART"],"note":"Nobody notices any of these until the day one of them is missing, at which point it is the only thing anybody notices."},{"name":"___ CHAIR","colour":"p","tiles":["ARM","HIGH","WHEEL","DECK"],"note":"Armchair, highchair, wheelchair, deckchair. Four seats, four completely different lives."}],"epilogue":"The purple is a trap built out of a job title: CHAIR cannot be a ___ CHAIR because it is the chair. POSTDOC, FELLOW and DEAN need a fourth colleague, and ARM, HIGH, WHEEL and DECK are already a full set of furniture."},
{"id":6,"title":"The Fellows","diff":4,"groups":[{"name":"SUMMER-FELLOW STARTER PACK","colour":"y","tiles":["LANYARD","LAPTOP STICKER","REUSABLE CUP","TOTE BAG"],"note":"By week three the lanyard is in a drawer, the sticker is on the laptop for life, and there are four identical tote bags under the desk."},{"name":"WORDS THAT MEAN 'MEETING'","colour":"g","tiles":["HUDDLE","SYNC","CATCH-UP","TOUCH BASE"],"note":"Three of them are sports metaphors and the fourth is what two clocks do. None of them is shorter than the meeting it describes."},{"name":"SLACK REACTIONS, BY EMOJI NAME","colour":"b","tiles":["EYES","TADA","ROCKET","PLUS ONE"],"note":"eyes means 'I have seen this and will not be replying', tada means 'shipped', rocket means 'shipping', and plus-one means 'I agree but not enough to type'."},{"name":"___ SHEET","colour":"p","tiles":["SPREAD","TIME","BALANCE","CHEAT"],"note":"Spreadsheet, timesheet, balance sheet, cheat sheet. Three of them are the same document at different levels of honesty."}],"epilogue":"HUDDLE is a Slack button AND a word for a meeting, which is the whole problem with the modern workplace in one tile. EYES, TADA, ROCKET and PLUS ONE are emoji and nothing else, so the Slack group fills itself and the huddle goes back to being a meeting."}
]},
{"id":"cambridge","name":"CAMBRIDGE MA","blurb":"Harvard Square, the Red Line, and the 02138 way of life.","boards":[
{"id":1,"title":"The Red Line","diff":2,"groups":[{"name":"STOPS ON THE RED LINE","colour":"y","tiles":["ALEWIFE","DAVIS","ASHMONT","BRAINTREE"],"note":"Alewife at the north end, and the line splits after JFK/UMass into the Ashmont and Braintree branches — which is why the sign matters."},{"name":"BRIDGES OVER THE CHARLES","colour":"g","tiles":["LONGFELLOW","WEEKS","ELIOT","ANDERSON"],"note":"The Longfellow is the salt-and-pepper one that carries the Red Line; Weeks is the footbridge everyone photographs; Anderson takes JFK Street across to the stadium."},{"name":"HARVARD SQUARE INSTITUTIONS","colour":"b","tiles":["THE COOP","CLUB PASSIM","OUT OF TOWN","THE PIT"],"note":"Club Passim is where Joan Baez played as a teenager. The Out of Town News kiosk sold papers from everywhere until 2019 and the shell is still there."},{"name":"___ SQUARE","colour":"p","tiles":["HARVARD","CENTRAL","INMAN","UNION"],"note":"Cambridge is organised entirely into squares, almost none of which are square."}],"epilogue":"PORTER and KENDALL would each have fitted both the station group and the square group, so neither is on this board — that is how a puzzle stays solvable. DAVIS is the one that got in, and ALEWIFE, ASHMONT and BRAINTREE keep it honest."},
{"id":2,"title":"The Yard","diff":2,"groups":[{"name":"HARVARD HOUSES","colour":"y","tiles":["ADAMS","LOWELL","ELIOT","KIRKLAND"],"note":"Twelve upperclass houses, assigned by lottery on Housing Day, and residents will argue about the ranking until they die."},{"name":"HARVARD GRADUATE SCHOOLS","colour":"g","tiles":["LAW","DESIGN","DIVINITY","KENNEDY"],"note":"The Divinity School is the oldest non-sectarian divinity school in the United States; the Kennedy School is across the river and knows it."},{"name":"IN HARVARD YARD","colour":"b","tiles":["WIDENER","JOHN HARVARD","MASS HALL","SEVER"],"note":"The statue is called the Statue of Three Lies: it isn't John Harvard, he didn't found the college, and the date is wrong."},{"name":"___ YARD","colour":"p","tiles":["SCOTLAND","JUNK","BACK","GRAVE"],"note":"Scotland Yard, junkyard, backyard, graveyard. Only one of them has a tourist problem."}],"epilogue":"No double agents here — the difficulty is knowing that Massachusetts Hall is a building and not a school, and that Sever is a lecture hall and not a house. Widener holds about 3.5 million volumes and is named for a man who died on the Titanic."},
{"id":3,"title":"02138","diff":3,"groups":[{"name":"CAMBRIDGE STREETS","colour":"y","tiles":["BRATTLE","MASS AVE","GARDEN","DUNSTER"],"note":"Brattle Street was Tory Row before the Revolution; the loyalists' houses are still standing and now hold seminars."},{"name":"MIT THINGS","colour":"g","tiles":["THE DOME","THE INFINITE","HACKS","STATA CENTER"],"note":"The Infinite Corridor is 251 m long and twice a year the sun lines up down the whole thing — MIThenge. The hacks have put a police car and a fire truck on the Dome."},{"name":"CAMBRIDGE FOOD LANDMARKS","colour":"b","tiles":["MR BARTLEY'S","TOSCANINI'S","DARWIN'S","FLOUR"],"note":"Bartley's has named a burger after every politician since the 1960s; Toscanini's ice cream was called the best in the world by the New York Times."},{"name":"COLLEGES WITHIN A BIKE RIDE","colour":"p","tiles":["TUFTS","LESLEY","BU","BERKLEE"],"note":"Lesley is in Cambridge, Tufts straddles Medford and Somerville, and Berklee has produced more Grammy winners than most countries."}],"epilogue":"MASS AVE runs from Harvard Square past MIT to Boston, which is exactly why it looks like it belongs in two places. THE DOME, THE INFINITE, HACKS and STATA CENTER are all inside one campus; Mass Ave merely goes past it."},
{"id":4,"title":"Town and Gown","diff":3,"groups":[{"name":"HARVARD TRADITIONS","colour":"y","tiles":["PRIMAL SCREAM","HOUSING DAY","COMMENCEMENT","THE GAME"],"note":"Primal Scream is a naked lap of the Yard at midnight before finals. The Game is Harvard–Yale, played since 1875, and 'The Game' is all anybody calls it."},{"name":"HARVARD STUDENT INSTITUTIONS","colour":"g","tiles":["THE CRIMSON","HASTY PUDDING","LAMPOON","GLEE CLUB"],"note":"The Lampoon is the oldest continuously published humour magazine in the world and its castle has a stolen ibis on the roof."},{"name":"VERY MASSACHUSETTS NOUNS","colour":"b","tiles":["PACKIE","ROTARY","JIMMIES","FRAPPE"],"note":"Liquor store, roundabout, sprinkles, and a milkshake with ice cream in it — order a 'milkshake' here and you get milk shaken with syrup."},{"name":"BOSTON ___","colour":"p","tiles":["CREAM PIE","TERRIER","MARATHON","TEA PARTY"],"note":"Boston cream pie is a cake, the Boston terrier is the state dog, and the marathon has been run on Patriots' Day since 1897."}],"epilogue":"TEA PARTY is the tile with two passports: a genuine Boston ___ compound and a genuinely Massachusetts thing. PACKIE, ROTARY, JIMMIES and FRAPPE are words you'd only hear said out loud, and that is the line that settles it."},
{"id":5,"title":"Head of the Charles","diff":4,"groups":[{"name":"ROWING WORDS","colour":"y","tiles":["COXSWAIN","ERG","REGATTA","SHELL"],"note":"The Head of the Charles is the largest three-day regatta in the world, about 11,000 athletes every October, and the Weeks Bridge turn is where races are won and lost."},{"name":"COMPANIES BASED IN CAMBRIDGE","colour":"g","tiles":["MODERNA","AKAMAI","HUBSPOT","BIOGEN"],"note":"Kendall Square is routinely called the most innovative square mile on earth, which is a marketing line that happens to be defensible."},{"name":"STREETS OFF HARVARD SQUARE","colour":"b","tiles":["JFK STREET","BOW STREET","PLYMPTON","HOLYOKE"],"note":"JFK Street was Boylston Street until 1981. Plympton holds the Grolier Poetry Book Shop, open since 1927 and selling nothing but poetry."},{"name":"PLACE NAMES FROM ALGONQUIAN LANGUAGES","colour":"p","tiles":["NANTUCKET","SWAMPSCOTT","MATTAPAN","SAUGUS"],"note":"Massachusetts itself is Algonquian — roughly 'at the great hill' — as are Mystic, Neponset, Cochituate and about half the map."}],"epilogue":"BOW STREET is a rowing word with a street sign on it, and this board has both. COXSWAIN, ERG, REGATTA and SHELL are already a full crew, so the bow stays on land — where, in fairness, it runs past a very good bookshop."},
{"id":6,"title":"Commencement","diff":5,"groups":[{"name":"PRESIDENTS OF HARVARD","colour":"y","tiles":["CONANT","PUSEY","BOK","SUMMERS"],"note":"Conant ran the place from 1933 to 1953 and helped build the atomic bomb in the middle of it; Bok served twice, twenty years apart."},{"name":"LIVED IN CAMBRIDGE","colour":"g","tiles":["JULIA CHILD","E E CUMMINGS","LONGFELLOW","ROBERT FROST"],"note":"Julia Child's kitchen on Irving Street was disassembled and rebuilt inside the Smithsonian. Longfellow's house on Brattle Street was Washington's headquarters first."},{"name":"LOCAL UNIVERSITY MOTTOES","colour":"b","tiles":["VERITAS","MENS ET MANUS","LUX ET VERITAS","PAX ET LUX"],"note":"Truth (Harvard), mind and hand (MIT), light and truth (Yale), peace and light (Tufts). Everybody wanted truth and only one of them got it unqualified."},{"name":"MBTA LINES","colour":"p","tiles":["RED","ORANGE","BLUE","SILVER"],"note":"Plus the Green Line. The colours were assigned in 1965: red for Harvard's crimson, green for the Emerald Necklace, blue for the harbour, orange for Orange Street."}],"epilogue":"The purple is four colours that aren't about colour, and the red one is named after the university in the group above it — the Red Line got its colour because it ends at Harvard. If you spent a while looking for a fifth motto, that's the board doing its job."}
]}
]
};
